style.css:
@-moz-document domain("yandex.ru"), domain("ya.ru") {
body, .homepage, .content, .main, .search2 {
        background: #0a0a0a !important;
        color: #a0ffa0 !important;
        font-family: 'Segoe UI', Arial, sans-serif !important;
    }

    /* Поисковая строка */
    .input__control, .search2__input {
        background: #111 !important;
        border: 2px solid #00cc66 !important;
        border-radius: 6px;
        color: #00ffaa !important;
        box-shadow: 0 0 8px #00aa55;
    }

    /* Кнопки */
    .button, .search2__button {
        background: linear-gradient(45deg, #003300, #007733) !important;
        border: 1px solid #00ff88 !important;
        color: white !important;
        border-radius: 4px;
        font-weight: bold;
    }

    /* Ссылки */
    a, .link {
        color: #00ff99 !important;
        border-bottom: 1px dashed #00aa66;
    }
    a:hover {
        color: #ffffff !important;
        text-shadow: 0 0 5px #00ffaa;
    }

    /* Блоки результатов */
    .serp-item {
        background: #111111 !important;
        border-left: 4px solid #00aa55 !important;
        padding: 10px;
        margin-bottom: 8px;
    }

    /* Лого */
    .logo {
        filter: brightness(1.2) hue-rotate(90deg);
    }

    /* Скроллбар */
    ::-webkit-scrollbar { width: 10px; }
    ::-webkit-scrollbar-track { background: #111; }
    ::-webkit-scrollbar-thumb { background: #008844; border-radius: 4px; }
}
